// the trigger lookup THROWS if that trigger never executed (e.g. this workflow
// run via Manual Trigger alone) — confirmed via live E2E testing. try/catch
// makes "never executed" and "executed with zero items" behave the same.
let trigger = {};
try {
  const triggerItems = $('When Executed by Another Workflow').all();
  trigger = triggerItems.length ? triggerItems[0].json : {};
} catch (e) { trigger = {}; }
const asOfDate = trigger.asOfDate || new Date().toISOString().slice(0, 10);

return $input.all().map((item) => ({ json: { ...item.json, asOfDate } }));

/**
 * helpers.js
 *
 * Shared low-level utilities used by every other module in /code and by the
 * equivalent n8n Code nodes. Pure functions only — no I/O, no n8n APIs — so
 * this file can be unit tested with plain `node` and pasted into a Code node
 * body unchanged (just drop the `module.exports` line).
 *
 * Candle shape (normalized, provider-agnostic — see docs/DATA_PROVIDER.md):
 * {
 *   symbol: "COMI",
 *   date: "2026-08-18",     // ISO date, trading session date
 *   open: 100.20,
 *   high: 103.10,
 *   low: 99.80,
 *   close: 102.70,
 *   volume: 12500000,
 *   tradedValue: 1270000000 // optional, derived if absent
 * }
